/* ===================== 缺失彙整與統計一覽表（期中、期末報告附錄） =====================
 * 列：缺失類別 → 缺失項目 → 缺失代碼（依數字分段排序），每個項目、類別結束後加合計列，最後總計。
 * 欄：管理處（標準順序）＋管理處合計、縣市政府（地理順序）＋縣市政府合計；只列有案件的單位。
 * 只計篩選範圍內「已建立缺失」的案件（已取消、已作廢不計）；0 顯示空白。
 */
const DS_OTHER = '其他（未對應代碼）';
const DS_CAT = ['品質管理制度', '施工品質', '施工進度', '規劃設計'];
/** 缺失代碼依數字分段比較：4.01.04.01 排在 4.01.05 前面 */
function cmpCode(a, b) {
  const x = String(a).split('.'), y = String(b).split('.');
  for (let i = 0; i < Math.max(x.length, y.length); i++) {
    if (x[i] == null) return -1; if (y[i] == null) return 1;
    const d = (parseInt(x[i], 10) || 0) - (parseInt(y[i], 10) || 0) || x[i].localeCompare(y[i]);
    if (d) return d;
  }
  return 0;
}
/** 產生一覽表：回傳 { grid（每格 {v,s,t}，被合併的格為 null）, merges:[[r1,c1,r2,c2]], head:表頭列數, rowCls:各列樣式 } */
function defSumModel(F) {
  const byId = {};
  S.stat.cases.forEach(c => { if (F.okCase(c) && c[SI.st] !== '已取消') byId[c[SI.id]] = c; });
  const D = S.stat.defects.filter(d => byId[d[0]] && d[3] > 0);
  // 單位與受檢工程數（有缺失的案件數）
  const ids = {}; D.forEach(d => { const u = byId[d[0]][SI.unit]; (ids[u] = ids[u] || {})[d[0]] = 1; });
  const us = Object.keys(ids).sort(cmpUnit), M = us.filter(u => kindOf(u) === '管理處'), K = us.filter(u => kindOf(u) !== '管理處');
  const short = u => String(u).replace(/管理處$/, '').replace(/政府$/, '');
  // 代碼 → [類別, 項目]；項目排序依該項目在缺失扣點表中最小的代碼
  const cats = S.stat.cats || {}, catOfCode = k => (cats[k] && cats[k][0]) ? cats[k] : [DS_OTHER, DS_OTHER];
  const itemMin = {}; Object.keys(cats).forEach(k => { if (!cats[k][0]) return; const ik = cats[k][0] + '｜' + cats[k][1]; if (!itemMin[ik] || cmpCode(k, itemMin[ik]) < 0) itemMin[ik] = k; });
  const catRank = c => c === DS_OTHER ? 999 : DS_CAT.indexOf(c) >= 0 ? DS_CAT.indexOf(c) : 100;
  const cnt = {};
  D.forEach(d => { const k = d[1] || '（未填代碼）', u = byId[d[0]][SI.unit]; const o = cnt[k] = cnt[k] || {}; o[u] = (o[u] || 0) + d[3]; });
  const codes = Object.keys(cnt).map(k => ({ k, c: catOfCode(k) })).sort((a, b) => catRank(a.c[0]) - catRank(b.c[0]) || a.c[0].localeCompare(b.c[0]) ||
    cmpCode(itemMin[a.c[0] + '｜' + a.c[1]] || '99', itemMin[b.c[0] + '｜' + b.c[1]] || '99') || a.c[1].localeCompare(b.c[1]) || cmpCode(a.k, b.k));
  // 數字欄：[管理處…, 管理處合計, 縣市政府…, 縣市政府合計]（沒有縣市政府案件時整組不顯示）
  const line = o => { const m = M.map(u => o[u] || 0), k = K.map(u => o[u] || 0), sm = m.reduce((a, b) => a + b, 0), sk = k.reduce((a, b) => a + b, 0); return K.length ? m.concat([sm], k, [sk]) : m.concat([sm]); };
  const add = (a, b) => { Object.keys(b).forEach(u => { a[u] = (a[u] || 0) + b[u]; }); return a; };
  const C = (v, s, t) => ({ v: v, s: s == null ? 1 : s, t: t });
  const nums = l => l.map(x => C(x || ''));
  const grid = [], merges = [], rowCls = [];
  const nU = M.length + 1 + (K.length ? K.length + 1 : 0);
  // 表頭（兩列）＋受檢工程數
  grid[0] = [C('缺失類別', 2), null, C('缺失代碼', 2), C('缺失(制式)', 2)].concat(M.length ? [C('管理處', 2)].concat(Array(M.length - 1).fill(null)) : [], [C('管理處合計', 2)],
    K.length ? [C('縣市政府', 2)].concat(Array(K.length - 1).fill(null), [C('縣市政府合計', 2)]) : []);
  grid[1] = [null, null, null, null].concat(M.map(u => C(short(u), 2)), [null], K.length ? K.map(u => C(short(u), 2)).concat([null]) : []);
  merges.push([0, 0, 1, 1], [0, 2, 1, 2], [0, 3, 1, 3]);
  if (M.length > 1) merges.push([0, 4, 0, 3 + M.length]);
  merges.push([0, 4 + M.length, 1, 4 + M.length]);
  if (K.length) { const k0 = 5 + M.length; if (K.length > 1) merges.push([0, k0, 0, k0 + K.length - 1]); merges.push([0, k0 + K.length, 1, k0 + K.length]); }
  const caseN = {}; us.forEach(u => { caseN[u] = Object.keys(ids[u]).length; });
  grid[2] = [C('受檢工程數', 2), null, null, null].concat(nums(line(caseN))); merges.push([2, 0, 2, 3]);
  rowCls[0] = rowCls[1] = rowCls[2] = 'h';
  // 內容列
  const total = {};
  let i = 0;
  while (i < codes.length) {
    const cat = codes[i].c[0], catSum = {}, catStart = grid.length;
    while (i < codes.length && codes[i].c[0] === cat) {
      const item = codes[i].c[1], itemSum = {}, itemStart = grid.length;
      while (i < codes.length && codes[i].c[0] === cat && codes[i].c[1] === item) {
        const k = codes[i].k; add(itemSum, cnt[k]);
        grid.push([C(cat), C(item), C(k, 1, 1), C(S.stat.codes[k] || '', 3)].concat(nums(line(cnt[k])))); rowCls.push('');
        i++;
      }
      if (grid.length - 1 > itemStart) merges.push([itemStart, 1, grid.length - 1, 1]);
      add(catSum, itemSum);
      if (item !== cat) {   // 項目名稱與類別相同（施工進度、其他）時只留類別合計，避免同名合計列重複
        grid.push([C(cat), C(item + '合計', 2), null, null].concat(nums(line(itemSum)))); merges.push([grid.length - 1, 1, grid.length - 1, 3]); rowCls.push('sub');
      }
    }
    if (grid.length - 1 > catStart) merges.push([catStart, 0, grid.length - 1, 0]);
    grid.push([C(cat + '合計', 2), null, null, null].concat(nums(line(catSum)))); merges.push([grid.length - 1, 0, grid.length - 1, 3]); rowCls.push('sub');
    add(total, catSum);
  }
  grid.push([C('總計', 2), null, null, null].concat(nums(line(total)))); merges.push([grid.length - 1, 0, grid.length - 1, 3]); rowCls.push('tot');
  // 被合併（非左上角）的格設為 null
  merges.forEach(m => { for (let r = m[0]; r <= m[2]; r++) for (let c = m[1]; c <= m[3]; c++) if (r !== m[0] || c !== m[1]) grid[r][c] = null; });
  return { grid, merges, head: 3, rowCls, nU, M, K, total: line(total), caseTotal: line(caseN) };
}
/** 檔名：缺失彙整一覽表_{年度}_{督導／查核／自訂} */
function defSumName(F) {
  const sel = [...$('stTypes').querySelectorAll('input:checked')].map(i => i.value);
  const kind = sel.length === 1 && sel[0] === '督導' ? '督導' : sel.length && sel.every(t => /查核/.test(t)) ? '查核' : '自訂';
  return '缺失彙整一覽表_' + (F.range ? (F.from || '') + '至' + (F.to || '') : (F.ys || []).slice().sort().join('-')) + '_' + kind;
}
function renderDefSum(F) {
  const T = defSumModel(F);
  S.defSum = T;
  if (T.grid.length <= 4) { $('tbDefSum').innerHTML = '<tbody><tr><td class="cnt">沒有資料</td></tr></tbody>'; return; }
  const span = {}; T.merges.forEach(m => { span[m[0] + ',' + m[1]] = m; });
  const cell = (o, r, c, tag) => {
    if (o === null) return '';
    const m = span[r + ',' + c], at = m ? (m[2] > m[0] ? ' rowspan="' + (m[2] - m[0] + 1) + '"' : '') + (m[3] > m[1] ? ' colspan="' + (m[3] - m[1] + 1) + '"' : '') : '';
    return '<' + tag + at + (o.s === 3 ? ' class="l"' : '') + '>' + esc(o.v) + '</' + tag + '>';
  };
  $('tbDefSum').innerHTML = '<thead>' + T.grid.slice(0, 2).map((r, ri) => '<tr>' + r.map((o, ci) => cell(o, ri, ci, 'th')).join('') + '</tr>').join('') + '</thead><tbody>' +
    T.grid.slice(2).map((r, k) => '<tr' + (T.rowCls[k + 2] === 'h' ? ' class="sub"' : T.rowCls[k + 2] ? ' class="' + T.rowCls[k + 2] + '"' : '') + '>' + r.map((o, ci) => cell(o, k + 2, ci, 'td')).join('') + '</tr>').join('') + '</tbody>';
}
$('btnDefSumXlsx').onclick = async () => {
  if (!S.stat) return;
  const F = statFilter(), T = defSumModel(F), name = defSumName(F);
  try {
    loading(true, '產生 Excel…');
    await xlsxBook(name, [{ name: '一覽表', grid: T.grid, merges: T.merges, widths: [12, 16, 12, 60].concat(Array(T.nU).fill(7)), freeze: T.head }]);
  } catch (e) { toast('Excel 產生失敗：' + errMsg(e), 4000); } finally { loading(false); }
};
$('btnDefSumSave').onclick = async () => {
  if (!S.stat) return;
  const F = statFilter(), T = defSumModel(F), name = defSumName(F);
  if (T.grid.length <= 4) { toast('沒有資料'); return; }
  try {
    loading(true, '存到雲端硬碟…');
    const r = await api('defSumSave', { name: name, head: T.head, merges: T.merges, rows: T.grid.map(row => row.map(o => o == null ? '' : o.v)) });
    $('defSumLink').innerHTML = '已' + (r.overwrite ? '覆寫' : '建立') + '：<a href="' + esc(r.url) + '" target="_blank" rel="noopener">' + esc(r.name) + '</a>';
    toast('已存到雲端硬碟「統計匯出」資料夾');
  } catch (e) { toast('存檔失敗：' + errMsg(e), 5000); } finally { loading(false); }
};
